mutations.before:
const { nextIndex, tombstoned } = draftOccupancy(state);
return {
  ...state,
  // `count` is untouched, on purpose. See the action's own comment.
  variation: {
    ...state.variation,
    occupancy: authoredOccupancy(nextIndex + 1, tombstoned),
  },
};

mutations.after:
const { nextIndex, tombstoned } = draftOccupancy(state);
const reused = tombstoned[0];
return {
  ...state,
  variation: {
    ...state.variation,
    occupancy:
      reused === undefined
        ? authoredOccupancy(nextIndex + 1, tombstoned)
        : authoredOccupancy(
            nextIndex,
            tombstoned.filter((slot) => slot !== reused),
          ),
  },
};
